const payload = $json.body || {};
const appointment = payload.appointment || {};
const patient = appointment.patient || {};
const professional = appointment.professional || {};

if (payload.event !== 'appointment.cancelled') {
  throw new Error('Evento invalido: esperado appointment.cancelled.');
}
if (!payload.event_id || !appointment.id || !appointment.google_event_id || !appointment.starts_at) {
  throw new Error('Payload incompleto: event_id, appointment.id, google_event_id e starts_at sao obrigatorios.');
}
function whatsappNumber(value, label) {
  let digits = String(value || '').replace(/\D/g, '');
  if (digits.length === 10 || digits.length === 11) digits = `55${digits}`;
  if (digits.length < 12 || digits.length > 13) throw new Error(`Telefone ${label} ausente ou invalido.`);
  return `${digits}@s.whatsapp.net`;
}
if (!patient.name || !professional.name) throw new Error('Nomes do paciente e do profissional sao obrigatorios.');
const startsAt = new Date(appointment.starts_at);
if (Number.isNaN(startsAt.getTime())) throw new Error('Data do agendamento invalida.');
const date = new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric' }).format(startsAt);
const time = new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit', hour12: false }).format(startsAt);
const reason = appointment.cancellation_reason ? `\nMotivo informado: ${appointment.cancellation_reason}` : '';
return [{ json: {
  eventId: payload.event_id,
  appointmentId: appointment.id,
  googleEventId: appointment.google_event_id,
  patientNumber: whatsappNumber(patient.phone, 'do paciente'),
  professionalNumber: whatsappNumber(professional.phone, 'do profissional'),
  patientMessage: `Ola, ${patient.name}. Sua desistencia do agendamento de ${date}, as ${time}, foi registrada.${reason}\n\nClinica Maieutica`,
  professionalMessage: `Ola, ${professional.name}. O atendimento de ${date}, as ${time}, foi cancelado por desistência do paciente ${patient.name}. O horario foi liberado.${reason}\n\nClinica Maieutica`
} }];
